/* Minimal HTMX-compatible GET/target/include subset used by this project. */
(function(){function qs(el,s){return el.closest('form')?.querySelector(s)||document.querySelector(s)}function params(el){const p=new URLSearchParams();if(el.name)p.set(el.name,el.value);(el.getAttribute('hx-include')||'').split(',').filter(Boolean).forEach(s=>{const x=qs(el,s.trim());if(x&&x.name)p.set(x.name,x.value)});return p}async function run(el){const url=new URL(el.getAttribute('hx-get'),location.href);params(el).forEach((v,k)=>url.searchParams.set(k,v));const r=await fetch(url,{headers:{'HX-Request':'true'}});if(!r.ok)return;const target=document.querySelector(el.getAttribute('hx-target'));if(target)target.innerHTML=await r.text()}document.addEventListener('change',e=>{const el=e.target.closest('[hx-get]');if(el)run(el)});let timer;document.addEventListener('keyup',e=>{const el=e.target.closest('[hx-get]');if(!el)return;clearTimeout(timer);timer=setTimeout(()=>run(el),350)});})();
